  function captureStar(){stars.title=document.querySelector<HTMLInputElement>('#star-title')?.value??stars.title;}
  function exportStars(){const c=document.createElement('canvas');c.width=800;c.height=800;const g=c.getContext('2d')!;g.fillStyle='#242d4b';g.fillRect(0,0,800,800);const points=starPoints(stars);g.strokeStyle=stars.color??STAR_COLORS[0];g.lineWidth=3;for(const [a,b]of stars.edges){if(!points[a]||!points[b])continue;g.beginPath();g.moveTo(points[a][0]*8,points[a][1]*8);g.lineTo(points[b][0]*8,points[b][1]*8);g.stroke();}g.fillStyle='#fff5c5';points.forEach(([x,y])=>{g.beginPath();g.arc(x*8,y*8,6,0,Math.PI*2);g.fill();});g.font='22px sans-serif';g.fillText(stars.title||'Маленькое небо · Респейс',25,765,750);downloadCanvas(c,'respace-stars.png');}
  function storyState():StoryState{return {stage:storyStage,choices:[...storySelections]};}
